# Judgement fields for run 0047 stage 2: Annex B, the Dublin descriptors. Force `describes`: the annex says they are "not meant to be prescriptive" and are not thresholds.
B = {}
def b(i, verbs, about, para, prac, ben): B['annex-b/' + i] = dict(verbs=verbs, about=about, para=para, prac=prac, ben=ben)
CY = {'short': ('qfehea:short', 'a short-cycle qualification', 'short cycle'), '1': ('qfehea:1', 'a first-cycle qualification (typically a bachelor\'s)', 'first cycle'), '2': ('qfehea:2', 'a second-cycle qualification (typically a master\'s)', 'second cycle'), '3': ('qfehea:3', 'a third-cycle qualification (a doctorate)', 'third cycle')}
b('short/b1', ['demonstrated', 'builds', 'provides'], 'knowledge at advanced-textbook level', 'Knowledge and understanding of a field built on secondary schooling, at the level of advanced textbooks, enough to underpin work, personal growth and study to the end of the first cycle.', 'Short-cycle graduates typically know a field at advanced-textbook level, building on school, as a base for work and further study.', 'At the end of a short-cycle course, you usually know your field at the level of advanced textbooks, enough to work in it or to study on.')
b('short/b2', ['apply'], 'applying knowledge at work', 'Applies knowledge and understanding in occupational settings.', 'Short-cycle graduates typically apply what they know in the workplace.', 'At the end of a short-cycle course, you can usually put what you know to use at work.')
b('short/b3', ['identify', 'use', 'formulate'], 'data for well-defined problems', 'Finds and uses data to answer well-defined problems, concrete and abstract.', 'Short-cycle graduates typically identify and use data to respond to well-defined problems.', 'At the end of a short-cycle course, you can usually find and use data to answer clearly set problems.')
b('short/b4', ['communicate'], 'communicating with peers, supervisors, clients', 'Communicates what they understand and do with peers, supervisors and clients.', 'Short-cycle graduates typically talk about their understanding and work with peers, supervisors and clients.', 'At the end of a short-cycle course, you can usually explain your work to colleagues, managers and clients.')
b('short/b5', ['undertake'], 'further study with some autonomy', 'Has the learning skills to study further with some autonomy.', 'Short-cycle graduates typically have the learning skills to go on studying with some independence.', 'At the end of a short-cycle course, you can usually go on studying with some independence.')
b('1/b1', ['demonstrated', 'builds', 'includes'], 'advanced-textbook knowledge touching the forefront', 'Knowledge and understanding built on secondary schooling, at advanced-textbook level, with some aspects informed by the forefront of the field.', 'First-cycle graduates typically know their field at advanced-textbook level, with some of it informed by the forefront.', 'At the end of a bachelor\'s, you usually know your field at the level of advanced textbooks, with some of it drawn from current research.')
b('1/b2', ['apply', 'indicates', 'demonstrated', 'devising', 'sustaining', 'solving'], 'professional approach; arguing and solving problems', 'Applies knowledge in a way that shows a professional approach, with competences shown by building arguments and solving problems in the field.', 'First-cycle graduates typically apply knowledge professionally, shown by sustained argument and problem-solving in their field.', 'At the end of a bachelor\'s, you can usually apply what you know in a professional way, making arguments and solving problems in your field.')
b('1/b3', ['gather', 'interpret', 'inform'], 'data to inform judgements, with reflection', 'Gathers and interprets relevant data to inform judgements that reflect on social, scientific or ethical issues.', 'First-cycle graduates typically gather and read data to make judgements that weigh social, scientific or ethical issues.', 'At the end of a bachelor\'s, you can usually gather and read data to make judgements, thinking about their social, scientific or ethical side.')
b('1/b4', ['communicate'], 'communicating to any audience', 'Communicates information, ideas, problems and solutions to specialists and non-specialists.', 'First-cycle graduates typically communicate ideas, problems and solutions to expert and lay audiences.', 'At the end of a bachelor\'s, you can usually explain ideas, problems and solutions to experts and non-experts.')
b('1/b5', ['developed', 'continue', 'undertake'], 'further study with high autonomy', 'Has the learning skills to go on studying with a high degree of autonomy.', 'First-cycle graduates typically have the learning skills for further study with much independence.', 'At the end of a bachelor\'s, you can usually go on studying largely on your own.')
b('2/b1', ['demonstrated', 'founded', 'extends', 'enhances', 'provides'], 'knowledge extending the first cycle; basis for originality', 'Knowledge and understanding that build on and extend the first cycle and ground original development or application of ideas, often through research.', 'Second-cycle graduates typically hold knowledge beyond the first cycle that lets them be original, often in research.', 'At the end of a master\'s, your knowledge usually goes past a bachelor\'s and lets you develop or apply ideas in original ways, often through research.')
b('2/b2', ['apply'], 'problem-solving in new, broader contexts', 'Applies knowledge and problem-solving in new or unfamiliar settings within broader or multidisciplinary contexts.', 'Second-cycle graduates typically apply knowledge and problem-solving in unfamiliar and multidisciplinary settings.', 'At the end of a master\'s, you can usually use what you know to solve problems in new settings and across subjects.')
b('2/b3', ['integrate', 'handle', 'formulate', 'reflecting'], 'integrating knowledge; judging on limited information', 'Integrates knowledge, handles complexity and forms judgements on incomplete information while reflecting on the social and ethical responsibilities involved.', 'Second-cycle graduates typically integrate knowledge, handle complexity and judge on limited information, mindful of social and ethical responsibility.', 'At the end of a master\'s, you can usually bring knowledge together, handle complexity and make judgements without full information, with an eye to their ethics.')
b('2/b4', ['communicate'], 'communicating conclusions and their basis', 'Communicates conclusions and the knowledge and reasoning behind them clearly and unambiguously to specialists and non-specialists.', 'Second-cycle graduates typically state their conclusions and reasoning clearly to any audience.', 'At the end of a master\'s, you can usually explain your conclusions and the reasons for them clearly to anyone.')
b('2/b5', ['allow', 'continue'], 'largely self-directed study', 'Has the learning skills to go on studying in a largely self-directed or autonomous way.', 'Second-cycle graduates typically have the learning skills for largely self-directed study.', 'At the end of a master\'s, you can usually direct your own further study.')
b('3/b1', ['demonstrated'], 'systematic understanding; mastery of research methods', 'Systematic understanding of a field and mastery of its research skills and methods.', 'Third-cycle graduates typically understand their field systematically and have mastered its research methods.', 'At the end of a doctorate, you usually understand your field systematically and have mastered its research methods.')
b('3/b2', ['demonstrated', 'conceive', 'design', 'implement', 'adapt'], 'running a substantial research process with integrity', 'Can conceive, design, carry out and adapt a substantial research process with scholarly integrity.', 'Third-cycle graduates typically conceive, design, run and adapt substantial research with integrity.', 'At the end of a doctorate, you can usually plan, run and adapt a major research project with integrity.')
b('3/b3', ['made', 'extends', 'developing', 'merits'], 'original contribution; publishable work', 'Has contributed original research that extends the frontier of knowledge through a substantial body of work, part of it worth refereed publication.', 'Third-cycle graduates typically contribute original research that pushes knowledge forward, some of it publishable.', 'At the end of a doctorate, you have usually added original research to your field, some of it good enough for refereed publication.')
b('3/b4', [], 'critical analysis and synthesis of new ideas', 'Analyses, evaluates and synthesises new and complex ideas critically.', 'Third-cycle graduates typically analyse, evaluate and synthesise new, complex ideas critically.', 'At the end of a doctorate, you can usually analyse, judge and bring together new and complex ideas.')
b('3/b5', ['communicate'], 'communicating with peers, scholars and society', 'Communicates about their expertise with peers, the wider scholarly community and society.', 'Third-cycle graduates typically talk about their expertise with peers, scholars and the public.', 'At the end of a doctorate, you can usually talk about your expertise with other researchers and with the public.')
b('3/b6', ['promote'], 'advancing society through knowledge', 'Can be expected to promote technological, social or cultural advancement in academic and professional settings.', 'Third-cycle graduates can typically be expected to drive technological, social or cultural progress in academic and professional settings.', 'At the end of a doctorate, you can usually be expected to help move technology, society or culture forward.')
